"""Recompute completed-run coverage and measured resource totals, without pooling scientific outcomes."""
import argparse,json,hashlib,datetime
from pathlib import Path
a=argparse.ArgumentParser();a.add_argument('namespace');a.add_argument('--final',action='store_true');args=a.parse_args();root=Path(args.namespace);results=root/'results'
expected=['technical_full_v1','pilot64_full_v1','validation299_full_v1','query_technical2_v1','query_pilot64_v1','query_validation299_v1','mediation_technical2_v1','mediation_pilot64_v1','mediation_validation299_v1']+[f'depth{d}_mediation_{suffix}' for d in (3,4) for suffix in ('technical2_v1','validation299_v1')]+[f'confirmation_{s}_{suffix}' for suffix in ('technical2_v1','full128_v1') for s in ('base','query','r2','r3','r4')]
runs=[];missing=[];subjects=set()
for name in expected:
 p=results/name;rp=p/'receipt.json'
 if not rp.exists():missing.append(name);continue
 receipt=json.loads(rp.read_text());assert receipt['status']=='COMPLETE';native=list(p.glob('*.native.json'));outputs=list(p.glob('*.results.json'));assert len(native)==len(outputs)==receipt['N'];resource=json.loads((p/'resource_summary.json').read_text());rowids=set()
 for path in outputs:
  q=json.loads(path.read_text());assert q['identity']==receipt['identity'];key=(q['split'],q['id']);assert key not in rowids;rowids.add(key);subjects.add(key)
 assert len(rowids)==receipt['N'] and not list(p.glob('*.partial'))
 if name.startswith('confirmation_'):assert json.loads((p/'scope_complete_checked.json').read_text())['n']==receipt['N']
 runs.append({'namespace':name,'technical':'technical' in name,'n_question_instances':receipt['N'],'scope':receipt.get('scope',receipt['identity'].get('experiment','ORIGINAL_KV_SIX_DIRECTION')),'receipt_sha256':hashlib.sha256(rp.read_bytes()).hexdigest(),'identity':receipt['identity'],'resources':resource})
if args.final:assert not missing,(missing,len(runs))
totals={'status':'COMPLETE' if not missing else 'IN_PROGRESS','n_planned_run_namespaces':len(expected),'n_complete_run_namespaces':len(runs),'missing_run_namespaces':missing,'unique_question_count':len(subjects),'run_question_instances_resource_only_not_independent_samples':sum(r['n_question_instances'] for r in runs),'n_recorded_model_forward_windows':sum(r['resources']['n_forward_windows'] for r in runs),'sum_recorded_forward_window_wall_seconds':sum(r['resources']['forward_wall_seconds_sum'] for r in runs),'sum_collector_receipt_wall_seconds':sum(r['resources']['collector_receipt_wall_seconds'] for r in runs),'sum_command_window_seconds_until_receipt':sum(r['resources']['command_window_seconds_until_receipt'] for r in runs),'max_recorded_forward_window_allocated_bytes':max(r['resources']['max_peak_allocated_bytes'] for r in runs),'max_recorded_forward_window_reserved_bytes':max(r['resources']['max_peak_reserved_bytes'] for r in runs),'max_process_cpu_maxrss_kib':max(r['resources']['process_cpu_maxrss_kib'] for r in runs),'GPU_scope':'Recorded forward-window maxima only; excludes model loading and between-forward hybrid/control construction and serialization. Not full-collector peak.','timing_scope':'CUDA-synchronized forward wall time includes host work within each forward. Collector timers include loading/collection/replay after preflight hashing. UTC command windows include preflight until receipt. These are not GPU kernel profiler times.','scientific_scope':'Separate cohort outcomes are not pooled; repeated conditions/technical questions are not independent sampling replicates. No outcomes are aggregated in this cost index.'}
(root/'EXECUTION_TOTALS.json').write_text(json.dumps(totals,indent=2));(root/'RUN_INDEX.json').write_text(json.dumps({'generated_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'summary':totals,'runs':runs},indent=2));print(json.dumps(totals))
